CREATE TABLE IF NOT EXISTS state_constituencies (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    code VARCHAR(50),
    lga_id INTEGER NOT NULL REFERENCES lgas(id) ON DELETE CASCADE,
    lga_name VARCHAR(255) NOT NULL,
    state_id INTEGER NOT NULL REFERENCES c_states(id) ON DELETE CASCADE,
    state_name VARCHAR(255) NOT NULL,
    senatorial_district_id INTEGER REFERENCES senatorial_districts(id) ON DELETE CASCADE,
    senatorial_district_name VARCHAR(255),
    federal_constituency_id INTEGER REFERENCES federal_constituencies(id) ON DELETE CASCADE,
    federal_constituency_name VARCHAR(255),
    wards_count INTEGER DEFAULT 0,
    polling_units_count INTEGER DEFAULT 0,
    status VARCHAR(50) DEFAULT 'active'
);

CREATE INDEX idx_state_constituencies_name ON state_constituencies (name);
CREATE INDEX idx_state_constituencies_code ON state_constituencies (code);
CREATE INDEX idx_state_constituencies_lga_id ON state_constituencies (lga_id);
CREATE INDEX idx_state_constituencies_state_id ON state_constituencies (state_id);
CREATE INDEX idx_state_constituencies_senatorial_district_id ON state_constituencies (senatorial_district_id);
CREATE INDEX idx_state_constituencies_federal_constituency_id ON state_constituencies (federal_constituency_id);

