ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, code = EXCLUDED.code, lga_id = EXCLUDED.lga_id, lga_name = EXCLUDED.lga_name, state_id = EXCLUDED.state_id, state_name = EXCLUDED.state_name, senatorial_district_id = EXCLUDED.senatorial_district_id, senatorial_district_name = EXCLUDED.senatorial_district_name, federal_constituency_id = EXCLUDED.federal_constituency_id, federal_constituency_name = EXCLUDED.federal_constituency_name, status = EXCLUDED.status;
-- SEED DATA END

